<div class="page-head"><div><h1><?= te('Private document proofs') ?></h1><p class="sub"><?= te('Upload evidence for office review. A proof upload alone does not complete I-9 verification or tax-form processing.') ?></p></div></div><?php if(!$configured): ?><div class="flash err"><?= te('An encryption key must be configured before documents can be uploaded or downloaded.') ?></div><?php endif; ?><?php if($configured): ?><form class="card" method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="do" value="upload"><?php if(!$isWorker): ?><label for="pf-who"><?= te('Whose document') ?></label><select id="pf-who" name="candidate_id" required><option value=""><?= te('Choose somebody…') ?></option><?php foreach($people as $person): ?><option value="<?= (int)$person['id'] ?>"><?= e($person['full_name']) ?></option><?php endforeach; ?></select><?php endif; ?><label><?= te('Document type / purpose') ?></label><input name="document_type" required maxlength="120"><label><?= te('PDF, JPEG or PNG · maximum 10 MB') ?></label><input type="file" name="proof" accept="application/pdf,image/jpeg,image/png" required><button class="btn"><?= te('Upload securely') ?></button></form><?php endif; ?><?php if(!$documents): ?><div class="card"><div class="empty"><?= te('No documents uploaded yet. A proof arrives when somebody uploads one here or from their private portal.') ?></div></div><?php endif; ?><?php foreach($documents as $d): ?><div class="card"><div class="page-heading m0 mb"><div><h2 class="m0"><?= e($d['full_name'] ?? t('Unknown person')) ?></h2><p class="small muted m0 mt-xs"><?= e($d['document_type']) ?> &middot; <?= te('uploaded :when', ['when' => d($d['created_at'])]) ?></p></div><span class="tag <?= $d['status']==='approved'?'green':($d['status']==='rejected'?'red':'amber') ?>"><?= te(ucfirst((string)$d['status'])) ?></span></div><?php if(trim((string)$d['review_note'])!==''): ?><p class="small"><?= e($d['review_note']) ?></p><?php endif; ?><?php if((int)($d['restricted']??0)): ?><span class="tag blue" data-restricted="<?= (int)$d['id'] ?>"><?= te('Identity document') ?></span> <?php endif; ?><?php if($d['can_open']): ?><a href="/proofs?download=<?= (int)$d['id'] ?>"><?= te('Download proof') ?></a><?php else: ?><span class="small muted" data-locked="<?= (int)$d['id'] ?>"><?= te('Restricted since it was validated: an administrator can open it.') ?></span><?php endif; ?><?php if(!$isWorker): ?><form class="row" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="review"><input type="hidden" name="document_id" value="<?= (int)$d['id'] ?>"><select name="status"><option value="approved"><?= te('approved') ?></option><option value="rejected"><?= te('rejected') ?></option></select><input name="review_note" placeholder="<?= te('Review note') ?>"><button class="btn"><?= te('Review') ?></button></form><?php endif; ?></div><?php endforeach; ?>
<?php if ($readers): ?>
<div class="card" id="identity-readers"><h2><?= te('Who may open identity documents') ?></h2>
  <p class="small muted"><?= te('Passports, Social Security cards, IDs, birth and citizenship papers and I-9s are encrypted. Once validated, only the worker, administrators and the people ticked here open them; the coordinator who checked them no longer can.') ?></p>
  <table><?php foreach ($readers as $r): ?><tr data-reader="<?= (int) $r['id'] ?>" data-allowed="<?= (int) $r['allowed'] ?>"><td><?= e($r['name']) ?> <span class="small muted"><?= e($r['role']) ?></span></td><td class="right"><form method="post" action="/proofs" class="inline"><?= csrf_field() ?><input type="hidden" name="do" value="identity_reader"><input type="hidden" name="user_id" value="<?= (int) $r['id'] ?>"><input type="hidden" name="allowed" value="<?= (int) $r['allowed'] ? '0' : '1' ?>"><button class="btn sm<?= (int) $r['allowed'] ? ' ghost' : '' ?>"><?= (int) $r['allowed'] ? te('Withdraw') : te('Authorize') ?></button></form></td></tr><?php endforeach; ?></table>
</div>
<?php endif; ?>
